\label{def:vi-main}
For $F:\mathbb R^d\to\mathbb R^d$, a solution $z_\star$ satisfies for all $z\in\mathbb R^d$
\[
 \langle F(z_\star),z-z_\star\rangle\ge0\;
 \;\Longleftrightarrow\;F(z_\star)=0.
\]
The algorithm starts from $z_0$ and does not know the root $z_\star$.
For the affine and composite models of
Sections~\ref{sec:affine-integrated} and~\ref{sec:acceleration-main}
we write $(G,x_0,x_\star)$ instead of $(F,z_0,z_\star)$.

\label{ass:sgc}
For $\rho\ge1$, every pre-call history $\mathcal F$ and every
$\mathcal F$-measurable query $z\in\mathbb R^d$ satisfy
\begin{equation*}
 \begin{aligned}
 \mathbb E[g(z,\xi)\mid\mathcal F]&=F(z),\\
 \mathbb E[\|g(z,\xi)\|^2\mid\mathcal F]
 &\le\rho\|F(z)\|^2.
 \end{aligned}
\end{equation*}

\label{ass:mixed}
For $\rho\ge1$ and $\sigma\ge0$, every pre-call history $\mathcal F$
and every $\mathcal F$-measurable query $z\in\mathbb R^d$ satisfy
\begin{equation*}
 \begin{aligned}
 \mathbb E[g(z,\xi)\mid\mathcal F]&=F(z),\\
 \mathbb E[\|g(z,\xi)-F(z)\|^2\mid\mathcal F]
 &\le(\rho-1)\|F(z)\|^2+\sigma^2.
 \end{aligned}
\end{equation*}

\label{ass:interpolation}
Let $F(z_\star)=0$. The oracle $g:\mathbb R^d\times\Xi\to\mathbb R^d$
satisfies
\[
 \begin{gathered}
 \mathbb E_\xi g(z,\xi)=F(z)\quad(\forall z\in\mathbb R^d),\\
 \sigma_\star^2:=\mathbb E_\xi\|g(z_\star,\xi)\|^2<\infty.
 \end{gathered}
\]
Interpolation is the case $\sigma_\star=0$, that is,
\begin{equation*}
 g(z_\star,\xi)=0\qquad\text{almost surely}.
\end{equation*}

\label{def:affine-risks-main}
Let $\mathcal E_d^{\rm aff,rel}$ and $\mathcal E_d^{\rm aff,mix}$ be the
minimax values, over the algorithms of Definition~\ref{def:ic-main}, of
the expected root-centered Minty gap $\mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat x)$
over Assumption~\ref{ass:affine-main} combined with
Assumption~\ref{ass:sgc} and with Assumption~\ref{ass:mixed},
respectively, for $F=G$, where
\begin{equation}\label{eq:aff:self-contained-gap}
 \operatorname{Gap}_\star^{\rm M}(x)=\sup_{\|u-x_\star\|\le R_0}
                       \langle G(u),x-u\rangle .
\end{equation}

\label{thm:affine-integrated}\label{thm:pure-affine-main}\label{pv:minimax}
Under Assumptions~\ref{ass:affine-main} and~\ref{ass:sgc}, for every
$m,K,N\in\mathbb N$, $L,R_0>0$, and $\rho\ge1$, there is a finite
dimension $d_{\rm hard}=O\bigl(m(KN)^2\bigr)$ such that
\begin{equation*}
 \mathcal E_{d_{\rm hard}}^{\rm aff,rel}
 =\Theta\!\left(\frac{LR_0^2}{1+ND_{\mathrm{info}}}\right).
\end{equation*}
The upper bound holds in every finite dimension. The lower bound uses
one fixed distribution of affine operators with unique roots.

\label{thm:affine-additive-main}\label{thm:affine-mixed-main}
Under Assumptions~\ref{ass:affine-main} and~\ref{ass:mixed}, for every
$m,K,N\in\mathbb N$, $L,R_0>0$, $\rho\ge1$, and $\sigma\ge0$, there is a
finite dimension $d_{\rm mix}=O\bigl(m(KN)^2\bigr)$ such that
\begin{equation*}
 \mathcal E_{d_{\rm mix}}^{\rm aff,mix}
 =\widetilde\Theta\!\Biggl(R_0^2\min\Biggl\{L,\ 
 \frac{L}{N}\min\!\left\{\frac\rho K,1+\frac\rho{mK}\right\}
 +\frac{\sigma}{R_0\sqrt{mKN}}\Biggr\}\Biggr).
\end{equation*}
where the upper bound holds up to a universal constant, in every finite
dimension, and the lower bound up to a universal multiple of $\log(2m)$. The hard
instances may have root noise exactly $\sigma^2$.

\label{vi:main-mixed-accuracy}
Under Assumptions~\ref{ass:monotone-lipschitz},
\ref{ass:strong-monotonicity}, and~\ref{ass:mixed}, let $\kappa\ge2$ and
$\|z_0-z_\star\|\le R_0$. For a universal constant $c>0$ let
$K_{\rm cq}=\min\{1,mK/\rho\}$ and
$\bar m_N=m/(1+m\,e^{-cNK_{\rm cq}/\kappa})$. There exists an admissible
algorithm attaining
\begin{equation*}
 \mathbb E\|\widehat z-z_\star\|^2\lesssim\min\Bigl\{R_0^2,\
 R_0^2e^{-cND_{\mathrm{sched}}/\kappa}
 +\frac{\sigma^2}{\mu^2\bar m_NKN}\Bigr\}.
\end{equation*}
Conversely, for universal constants $C,c'>0$ let $m_N=1$ if
$N\log(2m)\le c'\kappa$ and $m_N=m$ otherwise. In a sufficiently large
finite dimension, every admissible algorithm has an instance in this
class with
\begin{equation*}
 \mathbb E\|\widehat z-z_\star\|^2\gtrsim\max\Bigl\{
 R_0^2e^{-CND_{\mathrm{info}}/\kappa},\
 \min\Bigl\{R_0^2,\frac{\sigma^2}{\mu^2m_NKN}\Bigr\}\Bigr\}.
\end{equation*}

\label{ass:generalized-smoothness}
Let $L_0,R_0>0$ and $L_1\ge0$. The operator
$F:\mathbb R^d\to\mathbb R^d$ is continuously differentiable. Writing
$\mathrm DF(z)$ for its Jacobian at $z$, we require, for every
$z,u\in\mathbb R^d$,
\begin{equation*}
 \begin{aligned}
 \langle F(z)-F(u),z-u\rangle&\ge0,\\
 \|\mathrm DF(z)\|_{\rm op}&\le L_0+L_1\|F(z)\|.
 \end{aligned}
\end{equation*}
There is a root $z_\star$ with
$F(z_\star)=0$ and $\|z_0-z_\star\|\le R_0$.

For $x\in\mathbb R^d$, define
\begin{equation*}
 \operatorname{Gap}_{R_0}^{\mathrm{comp}}(x)
 =\sup_{\|u-x_\star\|\le R_0}
   \{f(x)-f(u)+\langle H(u),x-u\rangle\}.
\end{equation*}
The error is $\mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)$, with the
expectation outside the supremum.

\label{thm:composite-lower-main}
\label{interp:explicit-main}
\label{prop:composite-root-budget-main}
Let $0\le L_f\le L_{\max}$, $L_H\ge0$, $R_0>0$, $m,K,N\in\mathbb N$, and
$\nu\ge0$. In a common dimension of at most $2048m(KN)^2$, and in every
larger dimension,
\begin{equation*}
 \begin{multlined}
 \frac{\mathfrak R_{\rm comp}(\nu)}{R_0^2}
 =\Omega\!\Biggl(
 \frac{L_f}{(KN)^2}+\frac{L_H}{KN}
 \!+\!\min\!\left\{L_f,\frac{L_{\max}}{mKN}\right\}\\[-2pt]
 \quad ~ ~ +\min\!\left\{\frac{L_f}{(1+N\log m)^2},
              \frac{L_{\max}}{KN(1+N\log m)}\right\}\\[-2pt]
 \quad+\min\!\left\{L_f+L_H,
              \frac{\nu}{R_0\sqrt{mKN}}\right\}\Biggr).
 \end{multlined}
\end{equation*}
The first four terms are attained by interpolating instances.

\label{lem:clock:elementary}
For all the above parameters,
\begin{align*}
 \max\{Kp,(1-e^{-1})\min\{1,mKp\}\}
 &\le\beta_p\\
 &\le\min\{K,mKp,(e-1)Kp+\log m\}.\nonumber
\end{align*}

We begin by establishing a lower bound for $\beta_p$. First, observe that
\begin{equation*}
\beta_p = \mathbb E\max_{1\le i\le m} Z_i \ge \mathbb E Z_1 = Kp.
\end{equation*}
On the other hand, let $Z_{\max}=\max_{1\le i\le m}Z_i$. Since
$Z_{\max}\ge1$ on the event $\{Z_{\max}\ge1\}$, we have
$Z_{\max}\ge\mathbf 1_{\{Z_{\max}\ge1\}}$, and therefore
\begin{equation*}
\beta_p = \mathbb E Z_{\max} \ge \mathbb P(Z_{\max} \ge 1).
\end{equation*}
Now,
\begin{align*}
\mathbb P(Z_{\max} \ge 1)
&= 1 - \mathbb P(Z_{\max} = 0) = 1 - \prod_{i=1}^m \mathbb P(Z_i = 0) = 1 - (1-p)^{Km} \ge 1 - e^{-mKp},
\end{align*}
where the last inequality follows from $1 - p \le e^{-p}$.

Using the elementary bound $1 - e^{-x} \ge (1 - e^{-1}) \min\{1, x\}$, we obtain
\begin{equation*}
\beta_p \ge \max\left\{Kp,\ (1 - e^{-1}) \min\{1, mKp\} \right\}.
\end{equation*}

We now turn to the upper bound. It is immediate that
\begin{equation*}
\beta_p \le K
\quad\text{and}\quad
\beta_p \le mKp.
\end{equation*}
Next, note that for any $\eta_{\rm mgf}>0$
\begin{equation*}
e^{\eta_{\rm mgf}Z_{\max}}
=\max_{1\le i\le m}e^{\eta_{\rm mgf}Z_i}
\le\sum_{i=1}^m e^{\eta_{\rm mgf}Z_i}.
\end{equation*}
By Jensen's inequality,
\begin{equation*}
e^{\eta_{\rm mgf}\mathbb E Z_{\max}}
\le \mathbb E e^{\eta_{\rm mgf}Z_{\max}}
\le\sum_{i=1}^m\mathbb E e^{\eta_{\rm mgf}Z_i}
=m\bigl(1+p(e^{\eta_{\rm mgf}}-1)\bigr)^K .
\end{equation*}
Taking logarithms yields
\begin{equation*}
\beta_p
\le \frac{\log m+K\log(1+p(e^{\eta_{\rm mgf}}-1))}{\eta_{\rm mgf}}
\le \frac{\log m+Kp(e^{\eta_{\rm mgf}}-1)}{\eta_{\rm mgf}}.
\end{equation*}
For $\eta_{\rm mgf}=1$ this completes the proof.

\label{thm:clock:asymptotic}

Uniformly in all $m,K\ge1$ and $0<p\le1$,
\begin{equation*}
 \frac{D_{\mathrm{bin}}(m,K,p)}{64}\le\beta_p
 \le4D_{\mathrm{bin}}(m,K,p).
\end{equation*}
Consequently, for every $N\ge1$,
\begin{equation}\label{eq:clock:reciprocal}
 \frac{1+ND_{\mathrm{bin}}(m,K,p)}{64}\le1+N\beta_p
 \le4\bigl(1+ND_{\mathrm{bin}}(m,K,p)\bigr).
\end{equation}

\label{nn:identity-lemma}
For every $u\in\mathbb R^d$,
\begin{equation}\label{nn:identity}
 2\gamma\langle F(y),y-u\rangle
 =\|x-u\|^2-\|x^+-u\|^2+\gamma^2\mathcal R_{\rm eg}
 -2\gamma\bigl\langle\delta,\,x-\gamma F(y)-u\bigr\rangle,
\end{equation}
where
$\mathcal R_{\rm eg}=-\|F_x+e\|^2+\|F(y)-F_x-e\|^2+\|\delta\|^2$.
Moreover,
\begin{equation}\label{nn:pathwise-residual}
 \gamma^2\mathcal R_{\rm eg}\le-(1-2q_{\rm eg})\gamma^2\|F_x+e\|^2
       +2\gamma^2\|e\|^2+\gamma^2\|\delta\|^2.
\end{equation}

\label{nn:one-step}
\label{vi:seg-one-step}
Assume~\eqref{eq:eg-moments}, $\alpha_{\rm rel}\le1/4$ and
$0<\gamma\le1/(4L)$. Then
for every $u$ that is $\mathcal F$-measurable,
\begin{align}
 \mathbb E[\|x^+-u\|^2\mid\mathcal F]
 &\le\|x-u\|^2-2\gamma\,\mathbb E[\langle F(y),y-u\rangle\mid\mathcal F]
       -\frac7{128}\gamma^2\|F(x)\|^2+\frac{69}{32}\gamma^2\sigma_b^2,
       \label{nn:energy}\\
 \mathbb E[\|\delta\|^2\mid\mathcal F]
 &\le\frac{69}{32}\alpha_{\rm rel}\|F(x)\|^2
      +\frac{33}{32}\sigma_b^2.
       \label{nn:corrector}
\end{align}

\label{lem:dimref:projector}
Let $t,h\ge1$ and $s_{\rm G}\ge0$ be integers. For each
$j=1,\ldots,t$, let
\[
S_j=\operatorname{span}\{v^{\rm G}_{j,1},\ldots,v^{\rm G}_{j,s_{\rm G}}\}
\subseteq\mathbb R^h,
\]
where $v^{\rm G}_{j,1},\ldots,v^{\rm G}_{j,s_{\rm G}}$ are independent
$\mathcal N(0,I_h)$ vectors for each fixed $j$.
The collections corresponding to different indices $j$ may be
dependent. Let $e_1,\ldots,e_t\in\mathbb R^h$ be deterministic unit
vectors, and define
\[
p_j^{\rm proj}=\|\Pi_{S_j}e_j\|^2\in[0,1],
\]
where $\Pi_{S_j}$ denotes the orthogonal projector onto $S_j$.

If $h\ge16s_{\rm G}$, then
\begin{equation}
\mathbb{P}\!\left\{\max_{1\le j\le t}p_j^{\rm proj}>\frac12\right\}
\le2te^{-h/32}.
\label{eq:dimref:tail}
\end{equation}
Consequently, if
\begin{equation}
h\ge\max\{16s_{\rm G},32\log(8t)\},
\label{eq:dimref:dimension-condition}
\end{equation}
then
\begin{equation}
\mathbb E\sqrt{1-\max_{1\le j\le t}p_j^{\rm proj}}
\ge\frac3{4\sqrt2}>\frac12.
\label{eq:dimref:factor}
\end{equation}
For $s_{\rm G}=0$, we use the convention $S_j=\{0\}$.
Then $p_j^{\rm proj}=0$, and the expectation
in~\eqref{eq:dimref:factor} equals one for every $h\ge1$.

\label{nn:trajectory}
Run $T\ge1$ extragradient steps with a constant step size
$0<\gamma\le1/(4L)$ and independently sampled batches of size $b$, starting from $x_0$,
and let $\bar y=\frac1T\sum_{t<T}y_t$. Then
\begin{equation}\label{nn:trajectory-bound}
 \mathbb E\operatorname{Gap}_C^\diamond(\bar y)
 \le\frac{38}7\cdot\frac{D^2}{\gamma T}
       +\frac{69}{64}\cdot\frac{\gamma\sigma^2}{b}
       +\sqrt{\frac{33}{32}}\cdot\frac{D\sigma}{\sqrt{bT}}.
\end{equation}
For $\gamma=\min\{1/(4L),D\sqrt b/(\sigma\sqrt T)\}$, where the second
entry is $+\infty$ if $\sigma=0$,
\begin{equation}\label{nn:trajectory-optimized}
 \mathbb E\operatorname{Gap}_C^\diamond(\bar y)
 \le\frac{22LD^2}{T}
     +\frac{8\sigma D}{\sqrt{bT}}.
\end{equation}

\label{nn:all-budget}
Set $C_{\rm gap}:=440$. For all $m,K,N\in\mathbb N$, the better of the initial point and the two
schedules~\eqref{vi:all-budget-schedules}, chosen by their bounds, satisfies
\begin{equation}\label{nn:ic-upper}
 \mathbb E\operatorname{Gap}_C^\diamond(\widehat z)\le C_{\rm gap}\min\left\{
 LD^2,\quad
 \frac{\rho LD^2}{KN}+\frac{\sigma D}{\sqrt{KN}},\quad
 \frac{LD^2}{N\min\{1,mK/\rho\}}
       +\frac{\sigma D}{\sqrt{mKN}}
 \right\}
\end{equation}

\label{nn:strong-distance}
Let $F$ be in addition $\mu$-strongly monotone with $0<\mu\le L$, and
let $\|x_0-z_\star\|\le R_0$. One trajectory of $T\ge1$ steps with the
step sizes of Lemma~\ref{lem:two-phase-recursion}, where
$\gamma_0=1/(4L)$ and $\alpha=9\mu/8$. Set
$c_{\rm traj}:=3/32$ and $C_{\rm traj}:=1932/81$. Then
\begin{equation}\label{nn:strong-trajectory}
 \mathbb E\|x_T-z_\star\|^2
 \le R_0^2e^{-c_{\rm traj}\mu T/L}
       +\frac{C_{\rm traj}\sigma^2}{\mu^2bT}.
\end{equation}
Set $c_{\rm sched}:=3/640$ and $C_{\rm sched}:=96$. Consequently, the
better of the initial point and the two schedules~\eqref{vi:all-budget-schedules},
run with these step sizes, satisfies
\begin{align}\label{nn:strong-ic}
 \mathbb E\|\widehat z-z_\star\|^2\le C_{\rm sched}\min\bigg\{&R_0^2,\quad
 R_0^2e^{-c_{\rm sched}\mu KN/(\rho L)}
      +\frac{\sigma^2}{\mu^2KN},\nonumber\\[-2pt]
 &R_0^2e^{-c_{\rm sched}\mu N\min\{1,mK/\rho\}/L}
      +\frac{\sigma^2}{\mu^2mKN}\bigg\}
\end{align}
with universal constants shown above.
For $\sigma=0$ this is linear convergence.

\label{vi:all-budget}
Under SGC, the better of the initial point and the two
schedules~\eqref{vi:all-budget-schedules} satisfies
\begin{equation}\label{vi:all-gap}
 \mathbb E\operatorname{Gap}_C^\diamond(\widehat z)\le\frac{500LD^2}{1+ND_{\mathrm{sched}}}.
\end{equation}
Under strong monotonicity, the endpoint of the schedule with more steps
satisfies
\begin{equation*}
 \mathbb E\|\widehat z-z_\star\|^2
 \le D_0^2\min\left\{1,\ 2\exp\left[-\frac{9N}{320\kappa}D_{\mathrm{sched}}\right]\right\}.
\end{equation*}

\label{lem:relmm:masked}
Let
\begin{equation*}
 T_{\rm mask}=\min\bigl\{KN,\ \max\{1,\lceil2N\beta\rceil\}\bigr\},\qquad
 d_{\rm hard}=d_{\rm ref}(m,T_{\rm mask})\le1024\,m T_{\rm mask}^2,
\end{equation*}
with $d_{\rm ref}$ from Corollary~\ref{cor:dimref:depth}. There is a
fixed distribution of monotone affine $L$-Lipschitz operators on
$\mathbb R^{d_{\rm hard}}$, each with a unique root at distance $R_0$
from the initial point, and an oracle satisfying SGC with constant
$\rho$, such that every algorithm of Definition~\ref{def:ic-main}
satisfies
\begin{equation}\label{pv:minimax-comparison}
 \mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat x)
 \ge\frac{LR_0^2}{12T_{\rm mask}}
 \ge\frac{LR_0^2}{96(1+ND_{\mathrm{info}})}.
\end{equation}

\label{lem:relmm:upper}
There is a universal constant $C_0\ge6$ such that, under SGC and in
every dimension, an algorithm of Definition~\ref{def:ic-main} satisfies
\begin{equation}\label{eq:relmm:sharp-upper}
 \mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat x)
 \le LR_0^2\min\left\{1,\
       \frac{C_0\rho}{NK},\
       \frac{C_0}{N}\Bigl(1+\frac{\rho}{mK}\Bigr)\right\}.
\end{equation}

\label{pv:definition}
Set $z_0=x_0$. In round $r=0,\ldots,N-1$, every worker $i$ starts from
$x_{r,0}^i=z_r$ and performs, for $t=0,\ldots,T-1$,
\begin{align}\label{pv:algorithm}
 y_{r,t}^i&=x_{r,t}^i-\gamma\bigl(G(x_{r,t}^i)+e_{r,t}^i\bigr),\nonumber\\
 x_{r,t+1}^i&=x_{r,t}^i-\gamma\bigl(G(y_{r,t}^i)+\delta_{r,t}^i\bigr),
\end{align}
where $G(x_{r,t}^i)+e_{r,t}^i$ and $G(y_{r,t}^i)+\delta_{r,t}^i$ are
averages of $b$ independent responses at $x_{r,t}^i$ and at $y_{r,t}^i$; the
second batch is drawn after $y_{r,t}^i$ is computed. At the end of the
round the workers communicate and set
\begin{equation*}
 z_{r+1}=\frac1m\sum_{i=1}^m x_{r,T}^i.
\end{equation*}
The output is
$\widehat y=\frac1{mNT}\sum_{r<N}\sum_{i\le m}\sum_{t<T}y_{r,t}^i$;
each worker keeps the running sum of its points $y_{r,t}^i$ and sends it
at the last communication.

\label{pv:block}
Assume SGC, $0<\gamma\le1/(4L)$, and
\begin{equation}\label{pv:condition}
 \frac{c_{\rm avg}(1+\vartheta_{\rm grow})^{T-1}}{m}
 \le\frac{1-2q_{\rm eg}}2.
\end{equation}
Then the output of Definition~\ref{pv:definition} satisfies
\begin{equation}\label{pv:block-bound}
 \mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat y)\le\frac{3R_0^2}{\gamma NT}.
\end{equation}
For $\gamma=1/(4L)$ the bound is $12LR_0^2/(NT)$, and
condition~\eqref{pv:condition} reads
\begin{equation}\label{pv:explicit-condition}
 \alpha_{\rm rel}(35+\alpha_{\rm rel})
 \left(1+\frac{\alpha_{\rm rel}(18+\alpha_{\rm rel})}{256}\right)^{T-1}
 \le7m.
\end{equation}

\label{pv:comparison}
For all $m,K\ge1$ and $\rho\ge1$,
\begin{equation*}
 \beta\le1024\max\Bigl\{1,\frac K\rho,T_\star\Bigr\}.
\end{equation*}

\label{an:parallel}
If $\alpha_{\rm rel}=(\rho-1)/b\le1/8$ and
$0<\gamma\le1/(4L)$, then the output of
Definition~\ref{an:parallel-protocol} satisfies
\begin{equation}\label{an:parallel-certificate}
 \mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat y)
 \le\frac{4R_0^2}{\gamma T}
       +\frac{5\gamma\sigma^2}{2mb}
       +\frac{\sqrt3\,\sigma R_0}{\sqrt{mbT}}.
\end{equation}
In particular, for $\gamma=\min\{1/(4L),R_0\sqrt{mb}/(\sigma\sqrt T)\}$,
where the second entry is $+\infty$ if $\sigma=0$,
\begin{equation}\label{an:parallel-optimized}
 \mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat y)
 \le\frac{16LR_0^2}{T}+\frac{9\sigma R_0}{\sqrt{mbT}}.
\end{equation}

\label{an:mixed-explicit}
For every $m,K,N\in\mathbb N$ there is an algorithm of
Definition~\ref{def:ic-main} with
\begin{equation}\label{an:mixed-explicit-bound}
 \mathbb E\operatorname{Gap}_\star^{\rm M}(\widehat x)
 \le\min\left\{LR_0^2,\
       \frac{512LR_0^2}{N}\min\Bigl\{\frac\rho K,1+\frac\rho{mK}\Bigr\}
       +\frac{18\sigma R_0}{\sqrt{mKN}}\right\}.
\end{equation}

\label{an:statistical}
Under~\eqref{an:noise}, in every dimension $d\ge2$,
\begin{equation*}
 \mathcal E_d^{\rm aff,mix}
 \ge\frac3{128}\min\left\{LR_0^2,\
                         \frac{\sigma R_0}{\sqrt{mKN}}\right\}.
\end{equation*}
The hard instances are $L$-Lipschitz, have unique roots, and use a
Gaussian oracle whose variance equals $\sigma^2$ at every point.

\label{vi:affine-comparison}
For $r,\gamma>0$, the operator
\begin{equation}\label{vi:affine-chain}
 F_n(u,v)=\gamma\Bigl(D_n^\top v+\frac r{\sqrt n}e_1,\ -D_nu\Bigr)
\end{equation}
on $\mathbb R^n\times\mathbb R^n$ is monotone and $2\gamma$-Lipschitz, and its
root is $(0,-r\mathbf1/\sqrt n)$. On the product of two balls of radius
$r$ centered at $0$, the Minty gap and the primal--dual gap of
$\Phi_n(u,v)=\gamma(v^\top D_nu+ru_1/\sqrt n)$ coincide: for every
$(\widehat u,\widehat v)$ both equal
\begin{equation}\label{vi:affine-gap}
 \gamma\Bigl\{\frac r{\sqrt n}\widehat u_1+r\|D_n\widehat u\|
 +r\Bigl\|D_n^\top\widehat v+\frac r{\sqrt n}e_1\Bigr\|\Bigr\}
 \ \ge\ \frac{\gamma r}{\sqrt n}\Bigl|\widehat v_n+\frac r{\sqrt n}\Bigr|.
\end{equation}

\label{vi:core-root}
The operator $G_\epsilon$ is monotone and $\ell$-Lipschitz with
$\ell=1200\lambda$, and
\begin{equation}\label{vi:uniform-core-error}
 \|G_\epsilon(z)-G_0(z)\|\le
 \Delta_{\rm op}:=548\lambda\epsilon\sqrt{d_{\rm ch}}
 \qquad(z\in\mathbb R^{d_{\rm ch}}).
\end{equation}
It has a root within distance $548n\epsilon\sqrt{d_{\rm ch}}$ of
$z_{\rm ref}$. If $0\le s<d_{\rm ch}$ and all coordinates of $z$ after position $s$ have absolute
value at most $\epsilon$, then $\Phi_\epsilon(z)$ and $G_\epsilon(z)$ depend
only on the first $s+1$ coordinates of $z$.

\label{vi:strong-lower}
For the parameters~\eqref{vi:strong-params} and
$d_{\rm amb}\ge n+2(410R_{\rm loc})^2\epsilon^{-2}
\log(32mKNd_{\rm ch})$, every algorithm of
Definition~\ref{def:ic-main} on
$\mathbb R^{d_{\rm amb}}\times\mathbb R^{d_{\rm amb}}$ has a $C^2$,
$\mu$-strongly convex--concave instance with $L$-Lipschitz saddle
operator, a root $z_\star$ with $\|z_\star\|\le R_0$, and an oracle
satisfying SGC with equality, such that
\begin{equation*}
 \mathbb E\|\widehat z-z_\star\|^2\ge\frac{R_0^2q_{\rm geo}^{2k}}{50}.
\end{equation*}

\label{lem:smr-schedules}
Run the serial or the common-query schedule
of~\eqref{vi:all-budget-schedules} with the step sizes of
Proposition~\ref{nn:strong-distance} for $N\ge1$ rounds from a point $x$,
and return $x$ if the schedule makes no complete step. The output
$\widehat z$ satisfies, respectively,
\begin{align*}
 \mathbb E\|\widehat z-z_\star\|^2
 &\le96\Bigl[\|x-z_\star\|^2e^{-3NK_{\rm ser}/(640\kappa)}
      +\frac{\sigma^2}{\mu^2KN}\Bigr],\\
 \mathbb E\|\widehat z-z_\star\|^2
 &\le96\Bigl[\|x-z_\star\|^2e^{-3NK_{\rm cq}/(640\kappa)}
      +\frac{\sigma^2}{\mu^2mKN}\Bigr].
\end{align*}
The bounds also hold conditionally on a random starting point $x$.

\label{thm:strong-mixed-hybrid}
For all integers $m,K,N\ge1$ there is an algorithm of
Definition~\ref{def:ic-main}. Set $c_{\rm hyb}:=1/640$ and
$C_{\rm hyb}:=3\cdot96^2$. Then
\begin{equation}\label{eq:smr-hybrid}
 \mathbb E\|\widehat z-z_\star\|^2\le C_{\rm hyb}\min\Bigl\{R_0^2,\quad
 R_0^2e^{-c_{\rm hyb}N(K_{\rm ser}+K_{\rm cq})/\kappa}
 +\frac{\sigma^2}{\mu^2mKN}
   \bigl[1+m\,e^{-c_{\rm hyb}NK_{\rm cq}/\kappa}\bigr]\Bigr\}.
\end{equation}

\label{cor:strong-mixed-accuracy}
Suppose $\kappa\ge2$ and $0<\varepsilon_{\rm rel}<1/200$. Then
\begin{equation*}
 N^*_{\rm dist}(\varepsilon)=\Omega\!\left(\max\Bigl\{1,\
 \frac{\kappa\log(1/\varepsilon_{\rm rel})}{D_{\mathrm{info}}},\
 \frac{\sigma^2}{\mu^2mK\varepsilon}\Bigr\}\right),
\end{equation*}
and
\begin{equation}\label{eq:smr-round-upper}
 \begin{aligned}
 \mathcal T_{\rm ser}
   &:=\frac{\kappa}{K_{\rm ser}}\log\frac1{\varepsilon_{\rm rel}}
      +\frac{\sigma^2}{\mu^2K\varepsilon},\\
 \mathcal T_{\rm pool}
   &:=\frac{\kappa}{K_{\rm cq}}\log\frac1{\varepsilon_{\rm rel}}
      +\frac{\sigma^2}{\mu^2mK\varepsilon},\\
 \mathcal T_{\rm hyb}
   &:=\frac{\kappa}{K_{\rm ser}+K_{\rm cq}}
      \log\frac1{\varepsilon_{\rm rel}}
      +\frac{\kappa\log(2m)}{K_{\rm cq}}
      +\frac{\sigma^2}{\mu^2mK\varepsilon},\\
 N^*_{\rm dist}(\varepsilon)
   &=O\!\left(1+\min\{\mathcal T_{\rm ser},\mathcal T_{\rm pool},
                        \mathcal T_{\rm hyb}\}\right).
 \end{aligned}
\end{equation}

\label{nn:statistical-lower}
Every algorithm of Definition~\ref{def:ic-main} has an affine monotone
instance with $L$-Lipschitz operator, root at distance $D$ from
$z_0=0$, and an oracle with variance $\sigma^2$ at every point (so
Assumption~\ref{ass:mixed} holds for every $\rho\ge1$), such that
\begin{equation*}
 \mathbb E\operatorname{Gap}_{B(0,D)}^{\rm M}(\widehat z)
 \ge\frac3{128}\min\left\{LD^2,\
                   \frac{\sigma D}{\sqrt{mKN}}\right\}.
\end{equation*}

\label{gm:cube}
Let $r=D/4$ and $k=n-1$. If $\|x\|<R_{\rm cut}$ and all hidden coordinates of
$U^\top x$ after position $k$ are at most $\epsilon$ in absolute value, or
if $\|x\|\ge R_{\rm cut}$, then
\begin{equation*}
 \operatorname{Gap}^{\rm M}_{B(0,D)}(x)\ge\frac{\lambda r^2}{2n}.
\end{equation*}

\label{gm:hiding}
Let $S_N$ be as in Section~\ref{vi:haar-subsection}, with the bits
$B_{\rm mask}$ of
the oracle, and let $k\ge0$ be an integer with $\mathbb P\{S_N\le k\}\ge3/4$;
for instance $k=\min\{KN,\lfloor4N\beta_p\rfloor\}$. If
\begin{equation}\label{gm:dimension}
 d_{\rm amb}\ge d_{\rm ch}
 +\frac{2R_{\rm cut}^2}{\epsilon^2}\log(32mKNd_{\rm ch}),
\end{equation}
then for every algorithm of Definition~\ref{def:ic-main}, with probability
at least $5/8$ over the frame, the bits and the algorithm's randomness,
the output either has norm at least $R_{\rm cut}$ or has all hidden coordinates
after position $k$ at most $\epsilon$ in absolute value.

\label{gm:lower}\label{gm:frontier}
Let $0<p\le1$, $\sigma>0$, and
\begin{equation*}
 k=\min\{KN,\lfloor4N\beta_p\rfloor\},\quad n=k+1,\quad d_{\rm ch}=2n,\quad
 r=\frac D4,\quad a_{\rm ch}=\frac r{\sqrt n},\quad
 \lambda=\min\Bigl\{\frac L{120000},\ \frac{\sigma\sqrt{pn}}{9r}\Bigr\}.
\end{equation*}
In every dimension satisfying~\eqref{gm:dimension}, every algorithm of
Definition~\ref{def:ic-main} has an instance with monotone
$L$-Lipschitz operator, root in $B(0,D)$, and an oracle with
variance at most $\sigma^2$ at every point, such that
\begin{equation}\label{gm:lower-bound}
 \mathbb E\operatorname{Gap}^{\rm M}_{B(0,D)}(\widehat z)
 \ge c\min\left\{\frac{LD^2}{1+N\beta_p},\
 \frac{\sigma D\sqrt p}{\sqrt{1+N\beta_p}}\right\}
\end{equation}
with a universal $c>0$. In particular Assumption~\ref{ass:mixed} holds
for every $\rho\ge1$.

\label{gm:local-obstruction}
In the dimension of Theorem~\ref{gm:lower} with $p=1/K$, every algorithm
has an instance with
\begin{equation*}
 \mathbb E\operatorname{Gap}^{\rm M}_{B(0,D)}(\widehat z)
 =\Omega\!\left(\min\left\{\frac{LD^2}{Nh},\ \frac{\sigma D}{\sqrt{KNh}}\right\}\right).
\end{equation*}

\label{sf:root}
The operator $\mu I+\widehat G$ has a unique root $w_\star=(u_\star,v_\star)$,
and
\begin{equation*}
 \|w_\star\|<1.072\,r,\qquad
 (v_\star)_i<-0.928\,a_{\rm ch}\quad(1\le i\le n).
\end{equation*}

\label{sf:hiding}
Suppose $Nh\le n/64$. Let $p=n/(128KN)$ if $KN\ge n/128$ and $p=1$
otherwise, and let $k=\lfloor n/4\rfloor$. If
\begin{equation}\label{sf:dimension}
 d_{\rm amb}\ge d_{\rm ch}
 +\frac{2R_{\rm cut}^2}{\epsilon^2}\log(32mKNd_{\rm ch})
 =2n+10758400000000000000\,n^4\log(64mKNn),
\end{equation}
then for every algorithm there is a fixed frame $U$ such that, with
probability at least $1/2$ over the bits and the algorithm's randomness,
the output either has norm at least $R_{\rm cut}$ or has all hidden coordinates
after position $k$ at most $\epsilon$.

\label{sf:short-lower}
Let $\sigma>0$ and
\begin{equation}\label{sf:length}
 n=\Bigl\lfloor\frac{\kappa-1}{1872000}\Bigr\rfloor .
\end{equation}
If $n\ge1$ and $Nh\le n/64$, then in the dimension~\eqref{sf:dimension}
every algorithm has an instance with $\mu$-strongly monotone
$L$-Lipschitz operator, $\|z_0-z_\star\|\le R_0$, and an oracle with
variance at most $\sigma^2$, such that
\begin{equation*}
 \mathbb E\|\widehat z-z_\star\|^2
 \ge\min\left\{\frac{R_0^2}{80},\
       \frac{\sigma^2}{13271040\,\mu^2KN}\right\}.
\end{equation*}
If $KN<n/128$, the oracle is exact and the bound is $R_0^2/80$, also for
$\sigma=0$.

\label{sf:rate-lower}
Let $\kappa\ge2$ and $T_{\rm ch}=1872000$. In a sufficiently large
dimension, every algorithm of Definition~\ref{def:ic-main} has, for each
of the three quantities
\begin{equation*}
 \begin{gathered}
 \frac{R_0^2}{50}e^{-15372800ND_{\mathrm{info}}/\kappa},\qquad
 \frac3{128}\min\Bigl\{R_0^2,\frac{\sigma^2}{\mu^2mKN}\Bigr\},\\
 \mathbf 1\Bigl\{N\log(2m)\le\frac{\kappa}{256T_{\rm ch}}\Bigr\}
 \min\Bigl\{\frac{R_0^2}{80},\frac{\sigma^2}{13271040\,\mu^2KN}\Bigr\},
 \end{gathered}
\end{equation*}
an instance with a $\mu$-strongly monotone $L$-Lipschitz operator,
$\|z_0-z_\star\|\le R_0$, and an oracle satisfying
Assumption~\ref{ass:mixed}, on which $\mathbb E\|\widehat z-z_\star\|^2$ is at
least this quantity.

\label{sf:accuracy-lower}
For $\kappa\ge2$ and $0<\varepsilon_{\rm rel}<1/200$,
\begin{equation}\label{sf:accuracy-bridge}
 N^*_{\rm dist}(\varepsilon)=\Omega\!\left(\min\Bigl\{\frac\kappa h,\ s_1\Bigr\}\right),
\end{equation}
and, together with Corollary~\ref{cor:strong-mixed-accuracy},
\begin{equation}\label{sf:accuracy-full-lower}
 N^*_{\rm dist}(\varepsilon)=\Omega\!\Biggl(1
 +\frac{\kappa\log(1/\varepsilon_{\rm rel})}{D_{\mathrm{info}}}
 +\min\Bigl\{s_1,\ \frac\kappa h+s_m\Bigr\}\Biggr).
\end{equation}

\label{sf:accuracy-match}
For $\kappa\ge2$ and $0<\varepsilon_{\rm rel}<1/200$, the lower
bound~\eqref{sf:accuracy-full-lower} and the upper bound
\begin{equation}\label{sf:accuracy-full-upper}
 N^*_{\rm dist}(\varepsilon)=O\!\Biggl(1
 +\frac{\kappa\log(1/\varepsilon_{\rm rel})}
 {\max\{K/\rho,\min\{1,mK/\rho\}\}}
 +\min\bigl\{s_1,\ \kappa h+s_m\bigr\}\Biggr)
\end{equation}
differ by at most a factor $C\log^2(2m)$ with a universal $C$.

\label{grv:robust}
Fix a query $x$ determined by the history $\mathcal F$, a reference
magnitude $F_{\rm ref}>0$, a tolerance $\delta_{\rm rob}>0$, and a
failure probability $0<\tau_{\rm fail}<1$. Let
\begin{equation}\label{grv:robust-budget}
 n=\max\Bigl\{1,\Bigl\lceil\frac{256}{\delta_{\rm rob}^2}
       \Bigl(\rho-1+\frac{\sigma^2}{F_{\rm ref}^2}\Bigr)\Bigr\rceil\Bigr\},
 \qquad k=\max\{1,\lceil8\log(1/\tau_{\rm fail})\rceil\},\qquad b=nk .
\end{equation}
The geometric median $\widehat F_x$ of $k$ block means, each of $n$ independent
responses at $x$, satisfies
\begin{equation*}
 \mathbb P\bigl\{\|\widehat F_x-F(x)\|>
 \delta_{\rm rob}\max\{\|F(x)\|,F_{\rm ref}\}\bigm|\mathcal F\bigr\}
 \le\tau_{\rm fail} .
\end{equation*}
If $\rho=1$ and $\sigma=0$, one exact response is used instead ($b=1$). The
median is the minimum-norm minimizer of the sum of distances, which is
measurable and lies in the convex hull of the block means.

\label{grv:adaptive-stage}
Conditionally on any history at the start of the stage with
$\|c-z_\star\|\le r$, the output $z_{\rm out}(c,r)=x_{T_r}$ satisfies
\begin{equation*}
 \mathbb E\|z_{\rm out}(c,r)-z_\star\|^2\le\frac{r^2}{1024},
 \qquad
 \mathbb P\Bigl\{\|z_{\rm out}(c,r)-z_\star\|>\frac r8\Bigr\}\le\frac1{16}.
\end{equation*}
All queries and the output lie in $\mathcal B(c,r)$ on every history.
For a universal constant $C_{\rm stage}>0$,
\begin{equation}\label{grv:adaptive-stage-work}
 T_r\le C_{\rm stage}S_r,\qquad
 b_r\le C_{\rm stage}\Bigl(\rho+\frac{\sigma^2}{\mu^2r^2S_r}\Bigr)\log(64S_r),\qquad
 b_rT_r\le C_{\rm stage}\Bigl(\rho S_r+\frac{\sigma^2}{\mu^2r^2}\Bigr)\log(64S_r).
\end{equation}

\label{grv:restarted}
In every dimension, $\mathbb E\|c_J-z_\star\|^2\le\varepsilon$. The method uses
$2k_{\rm rep}\sum_{j<J}b_jT_j$ calls. For a universal constant
$C_{\rm rst}>0$,
\begin{equation}\label{grv:restart-sums}
 \sum_{j<J}T_j\le C_{\rm rst}A_{\rm rst},\qquad
 \sum_{j<J}b_jT_j\le C_{\rm rst}\ell_0
 \Bigl(\rho A_{\rm rst}+\frac{\sigma^2}{\mu^2\varepsilon}\Bigr).
\end{equation}

\label{ghs:upper}
For $j_{\rm sw}\in\{0,\ldots,J\}$, run stages $j<j_{\rm sw}$ on one
worker and stages $j\ge j_{\rm sw}$
with common queries. Then $\mathbb E\|\widehat z-z_\star\|^2\le\varepsilon$, with
\begin{equation}\label{ghs:exact-budget}
 \Bigl\lceil\frac{2k_{\rm rep}}K\sum_{j<j_{\rm sw}}b_jT_j\Bigr\rceil
 +2k_{\rm rep}\sum_{j_{\rm sw}\le j<J}T_j
      \Bigl\lceil\frac{b_j}{mK}\Bigr\rceil
\end{equation}
rounds. Choosing $j_{\rm sw}$ to minimize~\eqref{ghs:exact-budget}, the number of
rounds is at most
\begin{equation}\label{ghs:rate}
 \begin{aligned}
 \widetilde O\Bigl(&1
 +\min\Bigl\{\frac\rho K,1+\frac\rho{mK}\Bigr\}
       \Bigl[a_0^2+\kappa_0\log\frac{2R_0^2}{\varepsilon}\Bigr]\\
 &+\min\Bigl\{\frac{\sigma^2}{\mu^2K\varepsilon},\
 \kappa_0+\frac{\sigma L_1}{\mu\sqrt K}
 +\frac{\sigma^2}{\mu^2mK\varepsilon}\Bigr\}\Bigr)
 \end{aligned}
\end{equation}
where the tilde hides only logarithmic factors in $2+a_0$, $2+\kappa_0$ and
$2R_0^2/\varepsilon$.

\label{lem:composite:variance}\label{lem:samples:variance}
\label{prop:composite-potential-main}
\label{interp:samples-subsection}
For every query $x$, conditionally on the history before the call,
\begin{equation*}
 \operatorname{Var}(\nabla f_\xi(x))
 \le4L_{\max}\min\{D_f(x,x_\star),D_f(x_\star,x)\}+2\sigma_\star^2.
\end{equation*}
Under interpolation, $4L_{\max}$ can be replaced by $2L_{\max}$ and the
last term vanishes.

\label{prop:composite-schedules-main}
Under Assumption~\ref{ass:interp-main}, an algorithm of
Definition~\ref{def:ic-main} satisfies
\begin{equation}
 \mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)=O\!\left(R_0^2
 \min\left\{\begin{aligned}
 &L_f+L_H,\\[-2pt]
 &\frac{L_f}{(KN)^2}+\frac{L_H+L_{\max}}{KN}
       +\frac{\sigma_\star}{R_0\sqrt{KN}}
 \end{aligned}\right\}\right)
 \label{eq:comm-upper-main}
\end{equation}
and, if $K\ge3$, also
$\mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)=O\!\left(R_0^2\bigl(\frac{L_f}{N^2}
+\frac{L_H}N+\frac{L_{\max}}{mKN}+\frac{\sigma_\star}{R_0\sqrt{mKN}}\bigr)\right)$.

\label{comp-local:near}\label{thm:composite-local-resolvent}
If $N\ge D_{\rm loc}$, there is an algorithm of
Definition~\ref{def:ic-main} with output $\widehat x\in\mathcal X_{\rm loc}$ and
\begin{equation}\label{comp-local:near-bound}
 \begin{aligned}
 \mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)\le16R_0^2\Bigl[{}
 &\frac{32D_{\rm loc}^2L_f}{N^2}
 +\frac{16D_{\rm loc}L_{\max}}{mKN}\\
 &+\frac{64J_{\rm loc}L_H}{KN}
 +\frac{2\sqrt{2D_{\rm loc}}\,\sigma_\star}{R_0\sqrt{mKN}}\Bigr].
 \end{aligned}
\end{equation}

\label{comp-local:uniform}
If $N\ge D_{\rm loc}$, there is an algorithm of
Definition~\ref{def:ic-main} with
\begin{equation*}
 \mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)=O\!\Biggl(R_0^2\Bigl[
 \frac{D_{\rm loc}^2L_f}{N^2}+\frac{J_{\rm loc}L_H}{KN}
 +\sqrt{\frac{D_{\rm loc}L_{\max}L_f}{mKN}}\Bigr]
 +\sigma_\star R_0\sqrt{\frac{D_{\rm loc}}{mKN}}\Biggr).
\end{equation*}

\label{comp-pool:theorem}
For every $m,K\ge1$ and $N\ge2$ there is an algorithm of
Definition~\ref{def:ic-main} with
\begin{equation*}
 \mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)\le CR_0^2
 \min\Bigl\{L_f+L_H,\ L_f+\frac{L_H}{KN}
 +\sqrt{\frac{L_{\max}L_f}{mKN}}+\frac{\sigma_\star}{R_0\sqrt{mKN}}\Bigr\},
\end{equation*}
where $C$ is a universal constant.

\label{thm:comm-main}\label{interp:communication-lower}
Let $0<\lambda\le L_f\le L_{\max}$, $p=\lambda/L_{\max}$, and
\begin{equation*}
 n_{\rm dep}=\min\bigl\{KN,\ \max\{1,\lceil2N\beta_p\rceil\}\bigr\}.
\end{equation*}
There is a fixed distribution of instances of
Assumption~\ref{ass:interp-main} with $H=0$ and $\sigma_\star=0$, whose
mean $f$ is a convex $\lambda$-smooth quadratic and whose samples are
nonnegative, convex and $L_{\max}$-smooth, such that every algorithm
satisfies
\begin{equation}
 \mathbb E\operatorname{Gap}_{R_0}^{\mathrm{comp}}(\widehat x)
 \ge\frac{\lambda R_0^2}{576\,n_{\rm dep}^2}
 \ge\frac{\lambda R_0^2}{2304\,(1+N\beta_p)^2}
 \label{interp:comm-clock-lower}
 \ge\frac{\lambda R_0^2}{36864\,[1+ND_{\mathrm{bin}}(m,K,p)]^2},
\end{equation}
where $D_{\mathrm{bin}}(m,K,p)$ is defined in~\eqref{eq:clock:explicit-app}. The dimension is at
most $2048m(KN)^2$, and the bound holds even if the masks and the sample
values are revealed.

\label{prop:composite-full-noise-lower}
\label{prop:composite-root-noise}\label{comp-local:noise-lower}
For $\nu\ge0$,
\begin{equation*}
 \mathfrak R_{\rm comp}(\nu)\ge\frac7{2048}
 \min\Bigl\{(L_f+L_H)R_0^2,\ \frac{\nu R_0}{\sqrt{mKN}}\Bigr\}.
\end{equation*}
The instances are one-dimensional and have root noise exactly $\nu^2$.
